package org.maktabati.tv;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.storage.*;import android.provider.DocumentsContract;import java.io.*;
/** Android 9 scoped-volume consent, available even on DocumentsUIMinimal. */
final class UsbAccess {
 static final int REQUEST=783;
 static void request(Activity a){try{StorageManager sm=(StorageManager)a.getSystemService(Context.STORAGE_SERVICE);for(StorageVolume v:sm.getStorageVolumes())if(v.isRemovable()&&!v.isPrimary()&&"mounted".equals(v.getState())){Intent i=v.createAccessIntent(null);if(i!=null){a.startActivityForResult(i,REQUEST);return;}}throw new IOException();}catch(Exception e){new android.app.AlertDialog.Builder(a).setMessage("تعذر فتح طلب صلاحية القرص في نسخة النظام الحالية").setPositiveButton("حسنًا",null).show();}}
 static void accept(Activity a,Intent data)throws Exception{Uri u=data.getData();if(u==null||!"com.android.externalstorage.documents".equals(u.getAuthority()))throw new IOException();String id=DocumentsContract.getTreeDocumentId(u);boolean valid=false;for(UsbVolumes.Volume v:UsbVolumes.removable(a))if(id.equals(v.uuid+":"))valid=true;if(!valid)throw new IOException();a.getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}
 static Uri tree(Context c,File root){for(UriPermission p:c.getContentResolver().getPersistedUriPermissions())if(p.isReadPermission()&&p.isWritePermission()&&"com.android.externalstorage.documents".equals(p.getUri().getAuthority()))try{if(DocumentsContract.getTreeDocumentId(p.getUri()).equals(root.getName()+":"))return p.getUri();}catch(Exception ignored){}return null;}
 static Uri document(Context c,File root,File file)throws Exception{Uri tree=tree(c,root);if(tree==null)throw new IOException("امنح الوصول للقرص من قائمة المكتبة أولًا");String prefix=root.getCanonicalPath()+"/",path=file.getCanonicalPath();if(!path.startsWith(prefix))throw new IOException("خارج القرص");return DocumentsContract.buildDocumentUriUsingTree(tree,root.getName()+":"+path.substring(prefix.length()));}
 static boolean probe(Context c){for(UsbVolumes.Volume v:UsbVolumes.removable(c)){Uri t=tree(c,v.root);if(t==null)continue;Uri f=null;boolean ok=false;try{Uri root=DocumentsContract.buildDocumentUriUsingTree(t,DocumentsContract.getTreeDocumentId(t));f=DocumentsContract.createDocument(c.getContentResolver(),root,"application/octet-stream","Maktabati-write-test-"+java.util.UUID.randomUUID()+".tmp");try(OutputStream out=c.getContentResolver().openOutputStream(f)){out.write(new byte[]{1,2,3});}try(InputStream in=c.getContentResolver().openInputStream(f)){ok=in.read()==1&&in.read()==2&&in.read()==3&&in.read()==-1;}}catch(Exception ignored){}finally{if(f!=null)try{ok=DocumentsContract.deleteDocument(c.getContentResolver(),f)&&ok;}catch(Exception e){ok=false;}}if(ok)return true;}return false;}
}
